function makeUzi() {
  const gun = new THREE.Group();
  const K = gunKit(gun);
  // Stamped receiver with pressed ribs; the top cover and its cocking knob.
  K.slab([[-0.14, -0.04], [0.22, -0.04], [0.22, 0.078], [-0.122, 0.078], [-0.14, 0.06]], 0.098, gunBody, { bevel: 0.01 });
  for (const sx of [-1, 1]) for (let i = 0; i < 3; i++) K.box(0.006, 0.012, 0.3, gunMid, sx * 0.0495, 0.05 - i * 0.035, 0.04);
  K.slab([[-0.13, 0.074], [0.2, 0.074], [0.2, 0.098], [-0.11, 0.104], [-0.13, 0.094]], 0.09, gunMid, { bevel: 0.012 });
  K.cyl(0.014, 0.014, 0.03, gunDark, 0, 0.114, 0.11, null, 8, 'y');
  K.sph(0.016, gunDark, 0, 0.13, 0.11);
  // Sights with their protective ears.
  for (const sx of [-1, 1]) { K.box(0.008, 0.045, 0.03, gunAccent, sx * 0.022, 0.124, -0.08); K.box(0.008, 0.04, 0.02, gunAccent, sx * 0.018, 0.114, 0.2); }
  K.box(0.022, 0.03, 0.02, gunAccent, 0, 0.12, -0.08);
  K.box(0.005, 0.03, 0.006, gunAccent, 0, 0.115, 0.2);
  // Folding stock: struts along the sides and the butt plate.
  K.box(0.05, 0.06, 0.1, gunDark, 0, 0.04, -0.18, -0.15, 0, 0, null, 0.012);
  for (const sx of [-1, 1]) K.box(0.01, 0.012, 0.22, gunMid, sx * 0.04, 0.02, -0.12, 0.05);
  K.box(0.09, 0.06, 0.015, gunDark, 0, 0.0, -0.24, 0, 0, 0, null, 0.005);
  K.box(0.03, 0.03, 0.12, gunMid, 0.04, 0.05, -0.16, 0, 0.45, 0);
  // Grip with the grip safety at the back, the big trigger guard, trigger, selector.
  K.slab(gripOutline(-0.02, -0.1, 0.16, 0.08, 0.22, 0.2), 0.064, gunPoly, { bevel: 0.014, segs: 3 });
  K.box(0.03, 0.07, 0.02, gunDark, 0, -0.08, -0.07, 0.22);
  K.slab(gunBand([[0.088, -0.04], [0.09, -0.068], [0.078, -0.079], [0.03, -0.079], [0.018, -0.07]], 0.005), 0.014, gunDark, { bevel: 0.003 });
  K.slab(gunBand([[0.052, -0.04], [0.05, -0.056], [0.044, -0.066]], 0.0035), 0.01, gunAccent, { bevel: 0.002 });
  K.box(0.006, 0.02, 0.02, gunDark, -0.052, -0.02, 0.0);
  // Long stick mag (in front of the grip), with its baseplate.
  const mag = K.group(0, -0.22, 0.06);
  mag.rotation.x = 0.08;
  K.slab([[-0.04, 0.14], [0.04, 0.14], [0.04, -0.138], [-0.04, -0.138]], 0.05, gunAccent, { bevel: 0.006, parent: mag });
  for (const sx of [-1, 1]) K.box(0.004, 0.22, 0.01, gunDark, sx * 0.026, 0.0, 0.0, 0, 0, 0, mag);
  K.slab([[-0.044, -0.136], [0.046, -0.136], [0.046, -0.152], [-0.044, -0.154]], 0.058, gunDark, { bevel: 0.004, parent: mag });
  gun.userData.mag = mag;
  gun.userData.baseMagPos = mag.position.clone();
  gun.userData.baseMagRot = mag.rotation.clone();
  // Front of the receiver, the knurled barrel nut, the threaded barrel.
  K.slab([[0.18, -0.01], [0.34, -0.01], [0.34, 0.07], [0.18, 0.07]], 0.08, gunMid, { bevel: 0.016, segs: 3 });
  K.lathe([[0, 0.325], [0.035, 0.325], [0.035, 0.355], [0, 0.355]], gunDark, { y: 0.03, seg: 16 });
  for (let i = 0; i < 12; i++) { const a = i / 12 * Math.PI * 2; K.box(0.006, 0.006, 0.03, gunAccent, Math.cos(a) * 0.036, 0.03 + Math.sin(a) * 0.036, 0.34); }
  K.lathe([[0, 0.34], [0.017, 0.34], [0.017, 0.455], [0.02, 0.458], [0.02, 0.475], [0.012, 0.478], [0, 0.478]], gunAccent, { y: 0.03, seg: 12 });
  gunEffects(gun, new THREE.Vector3(0, 0.03, 0.48), 0.05, 2.8, 7, 0.005);
  gun.userData.laser.position.set(0, 0.03, 4.0);
  gun.userData.laserBaseZ = 0.45;
  gun.userData.barrelAssembly = null;
  gun.userData.slide = null;
  gunSuppressor(gun, K, 'uzi');   // CL-95
  return finishGun(gun);
}

function carryGunCopy(kind) {
  const src = weaponMeshes[kind];
  if (!src) return null;
  const g = src.clone(true);
  const lights = [];
  g.traverse((o) => { if (o.isLight) lights.push(o); });
  for (const l of lights) if (l.parent) l.parent.remove(l);
  const fx = new Set();
  for (const [k, v] of Object.entries(src.userData)) if (v && v.isObject3D && /laser|flash|reloadShell|beam|glow/i.test(k)) fx.add(v);
  const orig = [], copy = [];
  src.traverse((o) => { if (!o.isLight) orig.push(o); });
  g.traverse((o) => copy.push(o));
  orig.forEach((o, i) => { if (fx.has(o) && copy[i]) copy[i].visible = false; });
  g.userData = { carryKind: kind };
  g.visible = true;
  g.position.set(0, 0, 0); g.rotation.set(0, 0, 0);
  // Centre it on its own middle, so a long gun and a short one hang from the same point.
  const inv = new THREE.Matrix4(), m = new THREE.Matrix4(), v = new THREE.Vector3();
  g.updateMatrixWorld(true);
  inv.copy(g.matrixWorld).invert();
  const lo = new THREE.Vector3(Infinity, Infinity, Infinity), hi = new THREE.Vector3(-Infinity, -Infinity, -Infinity);
  g.traverse((o) => {
    if (!o.isMesh || !o.visible || !o.geometry || !o.geometry.attributes || !o.geometry.attributes.position) return;
    m.multiplyMatrices(inv, o.matrixWorld);
    const P = o.geometry.attributes.position;
    for (let i = 0; i < P.count; i += 3) { v.set(P.getX(i), P.getY(i), P.getZ(i)).applyMatrix4(m); lo.min(v); hi.max(v); }
  });
  const wrap = new THREE.Group();
  if (Number.isFinite(lo.x)) g.position.set(-(lo.x + hi.x) / 2 * g.scale.x, -(lo.y + hi.y) / 2 * g.scale.y, -(lo.z + hi.z) / 2 * g.scale.z);
  wrap.add(g);
  wrap.userData.length = Number.isFinite(lo.z) ? (hi.z - lo.z) * g.scale.z : 0.6;
  return wrap;
}

function gunExtLook(gun, w, on) {
  const ud = gun.userData, mag = ud.mag;
  if (!mag) return;
  if (EXT_GROWS[w]) {
    if (!ud.magBaseScale) ud.magBaseScale = mag.scale.clone();
    mag.scale.copy(ud.magBaseScale);
    if (on) { if (w === 'aa12') mag.scale.multiplyScalar(1.22); else mag.scale.y *= 1.45; }
    return;
  }
  if (ud.extLook === undefined) {
    ud.extLook = null;
    // The magazine's own extent (it is a group of parts), in its own frame.
    const lo = new THREE.Vector3(Infinity, Infinity, Infinity), hi = new THREE.Vector3(-Infinity, -Infinity, -Infinity), v = new THREE.Vector3();
    mag.updateMatrixWorld(true);
    const inv = new THREE.Matrix4().copy(mag.matrixWorld).invert(), m = new THREE.Matrix4();
    mag.traverse((o) => {
      if (!o.isMesh || !o.geometry) return;
      if (!o.geometry.boundingBox) o.geometry.computeBoundingBox();
      const bb = o.geometry.boundingBox; if (!bb) return;
      m.multiplyMatrices(inv, o.matrixWorld);
      for (const x of [bb.min.x, bb.max.x]) for (const y of [bb.min.y, bb.max.y]) for (const z of [bb.min.z, bb.max.z]) { v.set(x, y, z).applyMatrix4(m); lo.min(v); hi.max(v); }
    });
    if (Number.isFinite(lo.y)) {
      const h = hi.y - lo.y;
      const ext = mag.clone(true);
      ext.userData = {}; ext.name = 'extMagLook';
      ext.position.set(0, lo.y + h * 0.06 - hi.y * 0.48, 0); ext.rotation.set(0, 0, 0); ext.scale.set(1, 0.48, 1);
      ext.traverse((o) => { if (o.isMesh) o.castShadow = true; });
      mag.add(ext);
      ud.extLook = ext;
    }
  }
  if (ud.extLook) ud.extLook.visible = !!on;
}

function makeMortarMesh(matOverride = null, collapsed = false) {
  const root = new THREE.Group();
  // The parts below were authored with the muzzle leaning toward -Z, while
  // everything that aims or crews the mortar treats +Z as its front: the tube ended
  // up pointing back at the marine standing behind it. Turned round as one piece.
  const g = new THREE.Group();
  if (!collapsed) g.rotation.y = Math.PI;
  root.add(g);
  const steel = matOverride || new THREE.MeshStandardMaterial({ color: 0x3e4a3a, metalness: 0.6, roughness: 0.5 });
  const plate = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.46, 0.08, 12), steel);
  if (collapsed) { plate.position.set(0, 0.16, -0.1); plate.rotation.x = Math.PI / 2; }
  else plate.position.y = 0.04;
  g.add(plate);
  const tube = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.13, 1.25, 12), matOverride || gunMetal);
  if (collapsed) { tube.position.set(0, 0.62, 0); tube.rotation.x = 0; }
  else { tube.position.set(0, 0.62, 0.18); tube.rotation.x = -0.72; }
  tube.castShadow = true;
  g.add(tube);
  g.userData.tube = tube;
  const bipod = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.9, 6), steel);
  if (collapsed) { bipod.position.set(0.14, 0.62, 0.02); bipod.rotation.set(0, 0, 0); }
  else { bipod.position.set(0.3, 0.45, -0.25); bipod.rotation.z = 0.5; bipod.rotation.x = 0.35; }
  g.add(bipod);
  const bipod2 = bipod.clone();
  bipod2.position.x = -bipod.position.x;
  if (!collapsed) bipod2.rotation.z = -0.5;
  g.add(bipod2);
  root.userData.tube = g.userData.tube;
  return root;
}

function refreshArmoryRack(force) {
  const rack = house.armoryRack;
  if (!rack) return;
  const kinds = armoryDisplayKinds();
  const key = kinds.map(gunLookKey).join(',');
  if (!force && key === armoryRackKey) return;
  armoryRackKey = key;
  for (const c of rack.children.slice()) { rack.remove(c); disposeRackCopy(c); }
  const mountRow = (row, small) => {
    const copies = row.map((k) => {
      const g = rackGunCopy(k); if (!g) return null;
      g.rotation.set(small ? 0 : -Math.PI / 2, small ? Math.PI / 2 : 0, small ? 0 : Math.PI / 2);
      const b = new THREE.Box3().setFromObject(g);
      return { k, g, b, w: b.max.x - b.min.x };
    }).filter(Boolean);
    const gap = small ? 0.32 : 0.075;
    const width = copies.reduce((s, c) => s + c.w, 0) + Math.max(0, copies.length - 1) * gap;
    let x = 0.76 - width / 2;
    for (const { k, g, b, w } of copies) {
      // Bounds, not nominal gun length: attachments and asymmetric stocks seat correctly.
      g.position.set(x - b.min.x, small ? 3.34 - (b.min.y + b.max.y) / 2 : 0.96 - b.min.y, 0.40 - b.min.z);
      g.userData.rackKind = k; rack.add(g);
      const peg = new THREE.Mesh(RACK_PEG_GEO, RACK_PEG_MAT);
      peg.position.set(x + w / 2, small ? 3.34 : 0.945, 0.43); peg.raycast = rackNoRay; rack.add(peg);
      x += w + gap;
    }
  };
  mountRow(kinds.filter((k) => slotType(k) === 'primary'), false);
  mountRow(kinds.filter((k) => slotType(k) !== 'primary'), true);
  mirrorTrainingRack();   // CL-115
}
